python3 - <<'EOF'
import csv
from collections import defaultdict

apps_by_id = defaultdict(list)
for batch in ["batch-01","batch-02","batch-03"]:
    with open(f"office-exports/{batch}/applications.csv") as f:
        for row in csv.DictReader(f):
            apps_by_id[row["application_id"]].append((batch, row["revision"], row["revision_reason"], row["received_date"]))

multi = {k:v for k,v in apps_by_id.items() if len(v) > 1}
for k,v in multi.items():
    print(k, v)
EOF

